import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';
import { FiMapPin, FiPhone, FiUser, FiArrowLeft } from 'react-icons/fi';

const ProductDetail = () => {
    const { id } = useParams();
    const { user } = useAuth();
    const navigate = useNavigate();
    const [product, setProduct] = useState(null);
    const [loading, setLoading] = useState(true);
    const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);
    const [showContact, setShowContact] = useState(false);

    useEffect(() => {
        fetchProduct();
    }, [id]);

    const fetchProduct = async () => {
        try {
            // Esta chamada incrementa as visualizações no backend
            const response = await api.get(`/products/${id}`);
            setProduct(response.data.product);
        } catch (error) {
            toast.error('Produto não encontrado');
            navigate('/');
        } finally {
            setLoading(false);
        }
    };

    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    const getContactMethodIcon = (method) => {
        if (method === 'whatsapp') return '💚 WhatsApp';
        if (method === 'call') return '📞 Ligação';
        return '💚 WhatsApp / 📞 Ligação';
    };

    const handleContact = () => {
        if (!user) {
            toast.error('Faça login para ver o contato');
            navigate('/login');
            return;
        }
        setShowContact(true);
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
            </div>
        );
    }

    if (!product) return null;

    const isOwner = user && product.sellerId === user.id;

    return (
        <div className="max-w-4xl mx-auto">
            <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-gray-600 hover:text-primary-600 mb-4">
                <FiArrowLeft /> Voltar
            </button>

            <div className="bg-white rounded-xl shadow-md overflow-hidden">
                <div className="md:flex">
                    <div className="md:w-1/2">
                        <div className="h-80 bg-gray-100 flex items-center justify-center">
                            {product.photos && product.photos.length > 0 ? (
                                <img 
                                    src={`http://localhost:3001${product.photos[currentPhotoIndex]}`} 
                                    alt={product.title} 
                                    className="w-full h-full object-contain" 
                                />
                            ) : (
                                <span className="text-6xl">{getCategoryIcon(product.category)}</span>
                            )}
                        </div>
                        {product.photos && product.photos.length > 1 && (
                            <div className="flex gap-2 p-4 overflow-x-auto">
                                {product.photos.map((photo, idx) => (
                                    <button
                                        key={idx}
                                        onClick={() => setCurrentPhotoIndex(idx)}
                                        className={`w-16 h-16 rounded-lg overflow-hidden border-2 ${currentPhotoIndex === idx ? 'border-primary-600' : 'border-gray-200'}`}
                                    >
                                        <img 
                                            src={`http://localhost:3001${photo}`} 
                                            alt={`Foto ${idx + 1}`} 
                                            className="w-full h-full object-cover" 
                                        />
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                    <div className="p-6 md:w-1/2">
                        <h1 className="text-2xl font-bold mb-2">{product.title}</h1>
                        <div className="flex items-center gap-2 mb-4">
                            <span className={`px-2 py-1 rounded-full text-xs font-semibold ${product.condition === 'novo' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'}`}>
                                {product.condition === 'novo' ? 'Novo' : 'Semi-novo'}
                            </span>
                            <span className="text-sm text-gray-500">{product.category}</span>
                        </div>
                        <p className="text-3xl font-bold text-primary-600 mb-4">{product.price.toLocaleString()} Kz</p>
                        <div className="border-t border-b py-4 my-4">
                            <p className="text-gray-700 whitespace-pre-line">{product.description}</p>
                        </div>
                        <div className="space-y-3">
                            <div className="flex items-center text-gray-600">
                                <FiMapPin className="mr-2" />
                                <span>{product.location}</span>
                            </div>
                            <div className="flex items-center text-gray-600">
                                <FiUser className="mr-2" />
                                <span>Vendedor: {product.sellerName}</span>
                            </div>
                            
                            {/* Exibir número de visualizações */}
                            <div className="text-sm text-gray-500 mt-2">
                                👁️ {product.views || 0} visualizações
                            </div>
                            
                            {!isOwner && (
                                <>
                                    {showContact ? (
                                        <div className="bg-green-50 p-4 rounded-lg mt-4">
                                            <div className="flex items-center gap-2 text-green-600 mb-2">
                                                <FiPhone />
                                                <span className="font-semibold">{getContactMethodIcon(product.contactMethod)}</span>
                                            </div>
                                            <p className="text-lg font-bold text-green-700">{product.contactNumber}</p>
                                            {product.contactHours && (
                                                <p className="text-sm text-green-600 mt-1">⏰ {product.contactHours}</p>
                                            )}
                                            <p className="text-xs text-green-500 mt-2">Entre em contato diretamente</p>
                                        </div>
                                    ) : (
                                        <button
                                            onClick={handleContact}
                                            className="w-full bg-primary-600 text-white py-3 rounded-lg hover:bg-primary-700 transition mt-4"
                                        >
                                            Ver número do vendedor
                                        </button>
                                    )}
                                </>
                            )}
                            {isOwner && (
                                <div className="bg-blue-50 p-4 rounded-lg mt-4">
                                    <p className="text-blue-600 font-semibold">📌 Este é seu anúncio</p>
                                    <p className="text-sm text-blue-600 mt-1">
                                        Método: {getContactMethodIcon(product.contactMethod)}<br />
                                        Número: {product.contactNumber}
                                        {product.contactHours && <br />}⏰ {product.contactHours}
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ProductDetail;
